<script setup>
import { Grid3X3, Layers3, Map, ZoomIn, ZoomOut } from 'lucide-vue-next'
defineProps({ zoom:{type:Number,required:true}, showGrid:{type:Boolean,required:true}, layersOpen:{type:Boolean,required:true} })
